# PATCH_V2_1_GUARD_AUDIT_BEGIN
try {
  $__tbot_v21_root = 'C:\alpaca-bot\ORG_BOT_UNIFIED'
  $__tbot_v21_py   = 'C:\alpaca-bot\ORG_BOT_UNIFIED\code\.venv\Scripts\python.exe'
  $__tbot_v21_log  = 'C:\alpaca-bot\ORG_BOT_UNIFIED\runtime\paper\logs\hardening_events.jsonl'

  $__tbot_v21_cmd  = ""
  try {
    $__tbot_v21_cmd = (
      Get-CimInstance Win32_Process -Filter ("ProcessId=" + $PID) -ErrorAction Stop
    ).CommandLine
  } catch {
    $__tbot_v21_cmd = ""
  }

  $__tbot_v21_row = [ordered]@{
    ts                      = (Get-Date).ToString("s")
    kind                    = "wrapper_guard_audit_v2_1"
    wrapper                 = "ORG_UNIFIED_RUNTIME_MANAGER.ps1"
    canonical_root          = $__tbot_v21_root
    canonical_root_exists   = (Test-Path $__tbot_v21_root)
    canonical_python        = $__tbot_v21_py
    canonical_python_exists = (Test-Path $__tbot_v21_py)
    current_script          = $PSCommandPath
    current_location        = (Get-Location).Path
    env_pythonpath          = $env:PYTHONPATH
    env_tbot_runroot        = $env:TBOT_RUNROOT
    process_commandline     = $__tbot_v21_cmd
    script_under_unified    = [bool](($PSCommandPath -as [string]) -like "*ORG_BOT_UNIFIED*")
    pwd_under_unified       = [bool](((Get-Location).Path -as [string]) -like "*ORG_BOT_UNIFIED*")
    pythonpath_has_unified  = [bool](($env:PYTHONPATH -as [string]) -like "*ORG_BOT_UNIFIED*")
    runroot_has_unified     = [bool](($env:TBOT_RUNROOT -as [string]) -like "*ORG_BOT_UNIFIED*")
  }

  $__tbot_v21_dir = Split-Path -Parent $__tbot_v21_log
  if ($__tbot_v21_dir) {
    New-Item -ItemType Directory -Force -Path $__tbot_v21_dir | Out-Null
  }

  ($__tbot_v21_row | ConvertTo-Json -Compress -Depth 10) |
    Add-Content -LiteralPath $__tbot_v21_log -Encoding UTF8
} catch {
  # best-effort only
}
# PATCH_V2_1_GUARD_AUDIT_END
